export declare const providerApi = "\n<!DOCTYPE html>\n<html lang=\"fr\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Alerte Technique Fournisseur</title>\n\n<style>\n    body{\n        margin:0;\n        padding:0;\n        background-color:#f3f4f6;\n        font-family:Arial, Helvetica, sans-serif;\n        color:#111827;\n    }\n\n    .wrapper{\n        width:100%;\n        padding:40px 20px;\n        box-sizing:border-box;\n    }\n\n    .container{\n        max-width:620px;\n        margin:0 auto;\n        background:#ffffff;\n        border:1px solid #e5e7eb;\n        border-radius:10px;\n        overflow:hidden;\n    }\n\n    .header{\n        padding:28px 32px;\n        border-bottom:1px solid #e5e7eb;\n        background:#ffffff;\n    }\n\n    .header h1{\n        margin:0;\n        font-size:22px;\n        font-weight:600;\n        color:#b91c1c;\n    }\n\n    .header p{\n        margin:8px 0 0;\n        font-size:14px;\n        color:#6b7280;\n    }\n\n    .content{\n        padding:32px;\n    }\n\n    .content p{\n        margin:0 0 18px;\n        line-height:1.7;\n        font-size:15px;\n        color:#374151;\n    }\n\n    .alert-box{\n        margin:28px 0;\n        border:1px solid #fecaca;\n        background:#fef2f2;\n        border-radius:8px;\n        overflow:hidden;\n    }\n\n    .info-row{\n        display:flex;\n        padding:14px 18px;\n        border-bottom:1px solid #fecaca;\n        font-size:14px;\n    }\n\n    .info-row:last-child{\n        border-bottom:none;\n    }\n\n    .label{\n        width:190px;\n        font-weight:600;\n        color:#7f1d1d;\n    }\n\n    .value{\n        flex:1;\n        color:#991b1b;\n    }\n\n    .notice{\n        margin-top:30px;\n        padding-top:20px;\n        border-top:1px solid #e5e7eb;\n        font-size:14px;\n        line-height:1.7;\n        color:#6b7280;\n    }\n\n    .footer{\n        padding:20px 32px;\n        background:#f9fafb;\n        border-top:1px solid #e5e7eb;\n        font-size:12px;\n        color:#9ca3af;\n        text-align:center;\n    }\n\n    @media only screen and (max-width:600px){\n\n        .content,\n        .header,\n        .footer{\n            padding:24px;\n        }\n\n        .info-row{\n            display:block;\n        }\n\n        .label{\n            width:100%;\n            margin-bottom:6px;\n        }\n    }\n</style>\n</head>\n\n<body>\n\n<div class=\"wrapper\">\n\n    <div class=\"container\">\n\n        <!-- Header -->\n        <div class=\"header\">\n            <h1>Alerte technique fournisseur</h1>\n            <p>Incident d\u00E9tect\u00E9 sur un service externe</p>\n        </div>\n\n        <!-- Content -->\n        <div class=\"content\">\n\n            <p>Bonjour Administrateur,</p>\n\n            <p>\n                Une interruption ou anomalie a \u00E9t\u00E9 d\u00E9tect\u00E9e au niveau d\u2019un fournisseur externe.\n                Certains services de la plateforme peuvent \u00EAtre temporairement impact\u00E9s.\n            </p>\n\n            <!-- Alert Information -->\n            <div class=\"alert-box\">\n\n                <div class=\"info-row\">\n                    <div class=\"label\">API concern\u00E9e</div>\n                    <div class=\"value\">%api_endpoint%</div>\n                </div>\n\n                <div class=\"info-row\">\n                    <div class=\"label\">Code erreur</div>\n                    <div class=\"value\">%masked_error_code%</div>\n                </div>\n\n                <div class=\"info-row\">\n                    <div class=\"label\">Volume impact\u00E9</div>\n                    <div class=\"value\">%impacted_volume%</div>\n                </div>\n\n                <div class=\"info-row\">\n                    <div class=\"label\">Action recommand\u00E9e</div>\n                    <div class=\"value\">%recommended_action%</div>\n                </div>\n\n            </div>\n\n            <div class=\"notice\">\n                Cette alerte a \u00E9t\u00E9 g\u00E9n\u00E9r\u00E9e automatiquement par le syst\u00E8me de supervision.\n                Une v\u00E9rification technique est recommand\u00E9e afin d\u2019\u00E9valuer l\u2019impact\n                et assurer la continuit\u00E9 du service.\n            </div>\n\n        </div>\n\n        <!-- Footer -->\n        <div class=\"footer\">\n            \u00A9 %current_year% Plateforme SaaS SMS Marketing \u2014 Surveillance Technique\n        </div>\n\n    </div>\n\n</div>\n\n</body>\n</html>\n";
